<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { api, state, refreshCart, refreshUser, cartSubtotal, cartPrice } from '../lib/store.js'
import { personData, personFields, money } from '../lib/catalog.js'
import ValidatedForm from '../components/ValidatedForm.vue'
import Field from '../components/Field.vue'
import Notices from '../components/Notices.vue'
import CartLines from '../components/CartLines.vue'
import Icon from '../components/Icon.vue'
const router = useRouter(), customer = reactive(personData(state.user)), card = reactive({ number: '', expiry: '', cvc: '' }), shippingMethod = ref(''), saveAddress = ref(false), attempted = ref(false), busy = ref(false), error = ref('')
const shipping = computed(() => state.shipping.find(s => s.id === shippingMethod.value))
const total = computed(() => cartSubtotal() + (shipping.value?.price || 0))
onMounted(async () => { try { await refreshCart(); if (!state.cart.length) router.replace('/warenkorb'); if (state.user) { await refreshUser(); Object.assign(customer, personData(state.user)) } } catch (e) { error.value = e.message } })
async function submit() { attempted.value = true; if (!shippingMethod.value || !state.cart.length) return; busy.value = true; error.value = ''; try { const order = await api('/orders', { method: 'POST', body: { customer: { ...customer }, shippingMethod: shippingMethod.value, paymentMethod: 'card', items: state.cart.map(({ productId, color, size, quantity, designId, pocketRequest }) => ({ productId, color, size, quantity, designId: designId || null, pocketRequest: pocketRequest || '' })), ...(state.user && { saveAddress: saveAddress.value }) } }); state.lastOrder = order; Object.keys(card).forEach(key => { card[key] = '' }); await refreshCart(); if (state.user) await refreshUser(); router.push(`/bestellung/${order.id}`) } catch (e) { error.value = e.message } finally { busy.value = false } }
</script>
<template><section class="page checkout-page"><RouterLink to="/warenkorb" class="back-link">← Zurück zum Warenkorb</RouterLink><div class="page-intro"><span class="eyebrow">FAST BEI DIR</span><h1>Zur Kasse</h1></div><ValidatedForm v-if="state.cart.length" @submit="submit"><div class="checkout-layout"><div><section class="checkout-section"><h2><span class="step-number">01</span> Deine Lieferdaten</h2><div class="form-grid"><Field v-for="field in personFields" :key="field.name" v-model="customer[field.name]" v-bind="field" required :class="{ 'span-2': field.name === 'email' || field.name === 'street' }" /></div><label v-if="state.user" class="checkbox-label"><input v-model="saveAddress" type="checkbox">Diese Adresse in meinem Konto speichern</label></section><section class="checkout-section"><h2><span class="step-number">02</span> Versandart</h2><label v-for="option in state.shipping" :key="option.id" class="shipping-option" :class="{ selected: shippingMethod === option.id }"><input v-model="shippingMethod" type="radio" name="shipping" :value="option.id"><span>{{ option.name }}</span><strong>{{ money(option.price) }}</strong></label><p v-if="attempted && !shippingMethod" class="error-text" role="alert">Bitte wähle eine Versandart aus.</p></section><section class="checkout-section"><h2><span class="step-number">03</span> Kartenzahlung</h2><Field v-model="card.number" label="Kartennummer" pattern="[0-9]{16}" inputmode="numeric" autocomplete="off" hint="16 Ziffern ohne Leerzeichen" required /><div class="form-grid"><Field v-model="card.expiry" label="Ablaufdatum" pattern="(0[1-9]|1[0-2])/[0-9]{2}" inputmode="numeric" autocomplete="off" hint="Format MM/YY, zum Beispiel 12/28" required /><Field v-model="card.cvc" label="Sicherheitscode" pattern="[0-9]{3}" type="password" inputmode="numeric" autocomplete="off" hint="3 Ziffern" required /></div></section></div><aside class="summary-box checkout-summary"><h2>Deine Bestellung</h2><CartLines :items="state.cart" /><dl class="detail-list"><dt>Zwischensumme</dt><dd>{{ money(cartSubtotal()) }}</dd><dt>Versandkosten</dt><dd>{{ shipping ? money(shipping.price) : 'Bitte auswählen' }}</dd></dl><div class="row between summary-total"><strong>Gesamtpreis</strong><strong>{{ money(total) }}</strong></div><Notices :error="error" /><button class="button full-width" :disabled="busy" @click="attempted = true">{{ busy ? 'Bestellung wird aufgegeben …' : 'Zahlungspflichtig bestellen' }}<Icon name="arrow" /></button><p class="field-note">* Pflichtfelder</p></aside></div></ValidatedForm></section></template>
